import{_ as a,o as m,c as t,a2 as r}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"4-2 Dva 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/11.react(谢杰)/codestation后端/4-2 Dva 介绍.md","filePath":"DuOneClass/11.react(谢杰)/codestation后端/4-2 Dva 介绍.md"}'),l={name:"DuOneClass/11.react(谢杰)/codestation后端/4-2 Dva 介绍.md"};function o(i,e,s,p,c,n){return m(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_4-2-dva-介绍" tabindex="-1">4-2 Dva 介绍 <a class="header-anchor" href="#_4-2-dva-介绍" aria-label="Permalink to &quot;4-2 Dva 介绍&quot;">​</a></h1><p><em>Dva</em> 是一个基于 <a href="https://github.com/reduxjs/redux" target="_blank" rel="noreferrer">redux</a> 和 <a href="https://github.com/redux-saga/redux-saga" target="_blank" rel="noreferrer">redux-saga</a> 的数据流方案，可以理解为一个轻量级的应用框架。</p><p>官网：<em><a href="https://dvajs.com/" target="_blank" rel="noreferrer">https://dvajs.com/</a></em></p><p><em>Dva</em> 的本意，是将基于 <em>React</em> 技术栈中常用到的库集成到一起。当时，<em>React</em> 社区中最流行的应用架构方案如下：</p><ul><li>路由： <a href="https://github.com/ReactTraining/react-router/tree/v2.8.1" target="_blank" rel="noreferrer">React-Router</a></li><li>状态管理： <a href="https://github.com/reactjs/redux" target="_blank" rel="noreferrer">Redux</a></li><li>异步操作： <a href="https://github.com/yelouafi/redux-saga" target="_blank" rel="noreferrer">Redux-saga</a></li></ul><p>上面的架构中，除了 <em>Redux-saga</em> 我们没有介绍，前面两个我们都是有所接触的。</p><p>而 <em>Dva</em> 则是将上面三个 <em>React</em> 工具库包装在一起，简化了 <em>API</em>，让开发 <em>React</em> 应用更加方便和快捷。因此：</p><blockquote><p><em><strong>Dva = React-Router + Redux + Redux-saga</strong></em></p></blockquote><p><em>Redux-saga</em> 主要是为了处理数据流中异步操作的问题，虽然我们没有前面没有介绍，但是并不影响我们学习 <em>Dva</em>。</p><p><em>Dva</em> 中提供的数据流方案如下图：</p><p>数据流图1:</p><p><img src="https://s2.loli.net/2024/10/08/2YGocVprW4LJDmN.png" alt="image-20221105162108061"></p><p>数据流图2:</p><p><img src="https://s2.loli.net/2024/10/08/vDQ7YWb8lEKVdAn.png" alt="image-20221105162152274"></p><p><em>Dva</em> 中的核心概念如下：</p><ul><li><em>app.model</em><ul><li><em>namespace</em>: 当前 <em>Model</em> 的名称。整个应用的 <em>State</em>，由多个小的 <em>Model</em> 的 <em>State</em> 以 <em>namespace</em> 为 <em>key</em> 合成</li><li><em>state</em>: 该 <em>Model</em> 当前的状态。数据保存在这里，直接决定了视图层的输出</li><li><em>reducers</em>: <em>Action</em> 处理器，处理同步动作，用来算出最新的 <em>State</em></li><li><em>effects</em>：<em>Action</em> 处理器，处理异步动作，<em>Effect</em> 是一个 <em>Generator</em> 函数，内部使用 <em>yield</em> 关键字，标识每一步的操作（不管是异步或同步） <ul><li><em>dva</em> 提供多个 <em>effect</em> 函数内部的处理函数，比较常用的是 <code>call</code> 和 <code>put</code></li><li><em>call</em>：执行异步函数</li><li><em>put</em>：发出一个 <em>Action</em>，类似于 <em>dispatch</em></li></ul></li></ul></li></ul><p><em>Dva</em> 练习：学生管理系统</p><p>目前，<em>Dva</em> 已经被融入到了 <em>Umi</em> 当中，之后我们在 <em>Umi</em> 中可以以插件的形式开启 <em>Dva</em> 来管理应用的数据流。</p>',18)])])}const _=a(l,[["render",o]]);export{u as __pageData,_ as default};
